// transposing yonatan's https://twitter.com/zozuar/status/1618281672008675330


void mainImage( out vec4 o, vec2 u )
{
    float k = fract(iTime*.5), i=0., y = i, f;
    vec2  R = iResolution.xy,
          p = ( u+u - R ) / R.y / exp(k+2.);                // normalization & zoom

    for(o *= i ; i++ < 6. && y < .5; p -= round(p) )        // fractal loop ( try without y<.5 ;-) )
        o += smoothstep( f = fwidth(p.y), -f , p.y+.26 )    // antialias outer spiral arm
           * smoothstep( 0., min(.1,f+f) , .5 - abs(p.y) ), // antialias inner spiral arm
        p = vec2( y = atan(p.x,p.y)/1.05 + k + 2.,          // spiral transform
                  y = log(length(p)*2.7) - k/6.28 + y/6. );
     // p -= round(p);                                      // tiling along the spiral
}






